mapper.select:
SELECT id, execution_id, user_id, conversation_id, tool, args_hash, args_json,
       summary, risk, expires_at, status, attempt_count, started_at, finished_at, result,
       error_code, error_message, created_at, updated_at
FROM ai_tool_execution
WHERE user_id = #{userId}
  AND execution_id = #{executionId}

mapper.update:
UPDATE ai_tool_execution
SET status = 'SUCCEEDED', result = #{result}, error_code = NULL, error_message = NULL,
    finished_at = now(), updated_at = now()
WHERE user_id = #{userId}
  AND execution_id = #{executionId}
  AND status = 'RUNNING'

UPDATE ai_tool_execution
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage},
    finished_at = now(), updated_at = now()
WHERE user_id = #{userId}
  AND execution_id = #{executionId}
  AND status = 'RUNNING'

UPDATE ai_tool_execution
SET status = 'CANCELLED', finished_at = now(), updated_at = now()
WHERE user_id = #{userId}
  AND execution_id = #{executionId}
  AND status IN ('PENDING', 'APPROVED', 'FAILED')

UPDATE ai_tool_execution
SET status = 'CANCELLED', finished_at = now(), updated_at = now()
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND status IN ('PENDING', 'APPROVED')
